 local merged=Image(s.spec);merged:drawSprite(s,1);merged:saveAs(root..'/PNG/'..id..'.png');s:saveAs(root..'/'..id..'-master-v010.aseprite');f=io.open(dir..'/composite.rgba','wb');f:write(merged.bytes);f:close();f=io.open(dir..'/psd-layers.json','w');f:write(json.encode(meta));f:close();table.insert(all,{id=id,width=s.width,height=s.height,layers=#s.layers,notes='Distinct continuous native floor variant. Runtime crops 1645x940, no enlargement.'});Image(im,Rectangle(13,0,1645,940)):saveAs(root..'/runtime-PNG/floor_variant_'..i..'.png');s:close()
